"use client";

import { useCallback, useEffect, useMemo, useState, type ReactNode } from "react";
import useSWR from "swr";
import {
  DataGridProvider,
  DataGridRoot,
  DataGridHeader,
  DataGridBody,
  defineColumns,
  type DataChange,
} from "@/registry/default/components/data-grid/data-grid";
import { useDataGridPagination, DataGridPaginationBar } from "@/registry/default/components/data-grid-pagination/data-grid-pagination";
import { type DemoRow } from "./demo-data";
import { createRemoteServer } from "./fake-remote-server";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 100, flex: 1 },
  { id: "email", header: "Email", accessorKey: "email", type: "text", width: 130, flex: 2 },
  { id: "role", header: "Role", accessorKey: "role", type: "text", width: 90, flex: 1 },
  { id: "score", header: "Score", accessorKey: "score", type: "number", width: 70, flex: 1 },
] as const);

/**
 * Server-mode pagination through SWR: `useSWR(["rows", page, pageSize], fetcher)` fetches the
 * current page from the fake server (~300 ms) and caches it by key, so paging back is instant.
 * The last fetched rows are kept in local state so the grid keeps showing them while the next
 * page loads (SWR has no built-in keep-previous). Edits write through to the fake server, then
 * the scoped `mutate` revalidates the current key so the grid shows the server's truth.
 *
 * The fetcher receives the key itself as its argument (SWR 2.x convention), hence the tuple
 * cast rather than destructured parameters.
 */
function PaginatedSwrGrid(): ReactNode {
  const server = useMemo(() => createRemoteServer(), []);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState(25);
  const [rows, setRows] = useState<readonly DemoRow[]>([]);

  const { data, isLoading, mutate } = useSWR(["rows", page, pageSize] as [string, number, number], (key) =>
    server.fetchPage({ page: key[1], pageSize: key[2] }),
  );

  useEffect(() => {
    if (data) setRows(data.rows);
  }, [data]);

  const pager = useDataGridPagination({
    page,
    pageSize,
    total: data?.total ?? server.total,
    onPageChange: setPage,
    onPageSizeChange: (next) => {
      setPageSize(next);
      setPage(1);
    },
  });

  const onDataChange = useCallback(
    (_next: readonly DemoRow[], change: DataChange<DemoRow>) => {
      server.applyOps(change.ops);
      void mutate(undefined, { revalidate: true });
    },
    [mutate, server],
  );

  return (
    <div className="w-full flex flex-col gap-2">
      <div className="text-sm text-muted-foreground">
        {isLoading ? "Loading page…" : `Page ${pager.controls.page} of ${pager.controls.pageCount} · ${data?.total ?? 0} rows on the server`}
      </div>
      <div className="flex h-[420px] flex-col overflow-hidden rounded-md border border-border">
        <DataGridProvider data={rows} columns={columns} getRowId={(row) => row.id} onDataChange={onDataChange}>
          <DataGridRoot className="min-h-0 flex-1 rounded-none border-none">
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </DataGridProvider>
        <DataGridPaginationBar {...pager.controls} />
      </div>
    </div>
  );
}

export default function DataGridPaginationSwrDemo(): ReactNode {
  return <PaginatedSwrGrid />;
}

import { generateDemoRows, type DemoRow } from "./demo-data";

export type RemoteSort = { columnId: string; direction: "asc" | "desc" };
export type RemoteFilter = { columnId: string; operator: string; value?: string | [string, string] | string[] };
export type RemoteQuery = {
  page: number;
  pageSize: number;
  search?: string;
  sorts?: readonly RemoteSort[];
  filters?: readonly RemoteFilter[];
  join?: "and" | "or";
  signal?: AbortSignal;
};

const LATENCY_MS = 300;

function delay(signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(resolve, LATENCY_MS);
    signal?.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(new DOMException("aborted", "AbortError"));
    });
  });
}

/**
 * Fake "database" of 1,000 rows behind a 300 ms round trip for the server-side examples:
 * `fetchPage` applies search/filter/sort on the "server" and returns one page plus the total;
 * `applyOps` writes the grid's committed ops back into the store (a stand-in for your API route),
 * so edits survive a refetch.
 */
export function createRemoteServer() {
  const rows = new Map<string, DemoRow>(generateDemoRows(1000).map((row) => [row.id, row]));
  let order = [...rows.keys()];

  const cell = (row: DemoRow, columnId: string): string => {
    const value = row[columnId as keyof DemoRow];
    return value == null ? "" : String(value);
  };

  const matchFilter = (row: DemoRow, filter: RemoteFilter): boolean => {
    const text = cell(row, filter.columnId);
    const num = Number(text);
    const v = filter.value;
    switch (filter.operator) {
      case "contains":
        return text.toLowerCase().includes(String(v).toLowerCase());
      case "notContains":
        return !text.toLowerCase().includes(String(v).toLowerCase());
      case "equals":
        return text === String(v);
      case "notEquals":
        return text !== String(v);
      case "startsWith":
        return text.startsWith(String(v));
      case "endsWith":
        return text.endsWith(String(v));
      case "empty":
        return text === "";
      case "notEmpty":
        return text !== "";
      case "gt":
        return !Number.isNaN(num) && num > Number(v);
      case "gte":
        return !Number.isNaN(num) && num >= Number(v);
      case "lt":
        return !Number.isNaN(num) && num < Number(v);
      case "lte":
        return !Number.isNaN(num) && num <= Number(v);
      case "isBetween": {
        const [min, max] = v as [string, string];
        if (!Number.isNaN(num)) return (min === "" || num >= Number(min)) && (max === "" || num <= Number(max));
        return (min === "" || text >= min) && (max === "" || text <= max);
      }
      case "isAnyOf":
        return (v as string[]).includes(text);
      default:
        return true;
    }
  };

  async function fetchPage(query: RemoteQuery): Promise<{ rows: DemoRow[]; total: number }> {
    await delay(query.signal);
    let list = order.map((id) => rows.get(id)!);
    if (query.search) {
      const needle = query.search.toLowerCase();
      list = list.filter((row) => Object.values(row).some((value) => String(value).toLowerCase().includes(needle)));
    }
    const filters = query.filters ?? [];
    if (filters.length > 0) {
      list = list.filter((row) =>
        (query.join ?? "and") === "or"
          ? filters.some((f) => matchFilter(row, f))
          : filters.every((f) => matchFilter(row, f)),
      );
    }
    const sorts = query.sorts ?? [];
    if (sorts.length > 0) {
      list = [...list].sort((a, b) => {
        for (const s of sorts) {
          const av = a[s.columnId as keyof DemoRow];
          const bv = b[s.columnId as keyof DemoRow];
          const delta = typeof av === "number" && typeof bv === "number" ? av - bv : String(av).localeCompare(String(bv));
          if (delta !== 0) return s.direction === "asc" ? delta : -delta;
        }
        return 0;
      });
    }
    const total = list.length;
    const start = (query.page - 1) * query.pageSize;
    return { rows: list.slice(start, start + query.pageSize), total };
  }

  function applyOps(ops: readonly { type: string; rowId: string; row: DemoRow; index?: number; to?: number }[]): void {
    for (const op of ops) {
      if (op.type === "delete") {
        rows.delete(op.rowId);
        order = order.filter((id) => id !== op.rowId);
      } else {
        rows.set(op.rowId, op.row);
        if (op.type === "insert") order.splice(Math.min(op.index ?? order.length, order.length), 0, op.rowId);
        if (op.type === "move") {
          order = order.filter((id) => id !== op.rowId);
          order.splice(Math.min(op.to ?? 0, order.length), 0, op.rowId);
        }
      }
    }
  }

  return { total: rows.size, fetchPage, applyOps };
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const ADJECTIVES = ["Eager", "Quick", "Silent", "Bold", "Swift"] as const;
const NOUNS = ["Eagle", "Lion", "Tiger", "Bear", "Wolf"] as const;

/** Generates `count` deterministic demo rows for example previews (seed 42, stable across renders). */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  for (let i = 0; i < count; i++) {
    rows.push({
      id: `row-${i}`,
      name: `${ADJECTIVES[Math.floor(next() * ADJECTIVES.length)]} ${NOUNS[Math.floor(next() * NOUNS.length)]}`,
      email: `user${i}@example.com`,
      age: Math.floor(next() * 50) + 18,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
